package io.github.diodeme.ji.agent.core;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.github.diodeme.ji.agent.AgentRuntimeBuilder;
import io.github.diodeme.ji.agent.AgentSession;
import io.github.diodeme.ji.extension.PermissionDecider;
import io.github.diodeme.ji.agent.SessionOptions;
import io.github.diodeme.ji.agent.ToolDefinition;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.extension.PromptContributor;
import io.github.diodeme.ji.extension.ResourceDescriptor;
import io.github.diodeme.ji.session.memory.MemorySessionStore;
import io.github.diodeme.ji.testkit.ScriptedModelProvider;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.List;
import java.util.Map;
import java.util.concurrent.AbstractExecutorService;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;

class AgentRuntimeContractTest {
    private static final Usage FIRST_USAGE = new Usage(3, 2, 0, 0, 5);
    private static final Usage SECOND_USAGE = new Usage(5, 3, 0, 0, 7);

    @Test
    void completesStreamingToolPermissionUsageAndReloadFromCanonicalStore() {
        var provider = toolScript();
        var store = new MemorySessionStore();
        var executions = new AtomicInteger();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(store)
                .tool(ToolDefinition.sync("echo", "Echo input", Map.of("type", "object"), (arguments, cancellation) -> {
                    executions.incrementAndGet();
                    return ToolDefinition.ToolResult.text("echoed " + arguments.get("value"));
                }))
                .permissionDecider((request, cancellation) -> java.util.concurrent.CompletableFuture.completedFuture(PermissionDecider.Decision.allow(request, java.time.Instant.now())))
                .idGenerator(new SequentialIds()).clock(Clock.fixed(Instant.parse("2026-09-04T00:00:00Z"), ZoneOffset.UTC))
                .build()) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            assertEquals(io.github.diodeme.ji.agent.AgentEvent.Outcome.COMPLETED,
                    session.prompt("hello").completion().toCompletableFuture().join().outcome());
            assertEquals(1, executions.get());
            assertEquals(List.of("hello", "", "echoed hello", "done"), session.transcript().stream().map(message -> message.text()).toList());
            assertEquals("call-1", session.transcript().get(2).toolCallId().orElseThrow());
            assertEquals(13, store.load(session.id()).orElseThrow().usage().totalTokens());
            assertEquals(session.transcript(), runtime.loadSession(session.id()).transcript());
            assertEquals(2, provider.capturedRequests().size());
            assertEquals(3, provider.capturedRequests().get(1).messages().size());
        }
    }

    @Test
    void abortsBlockedProviderAndClearsActiveRun() {
        var gate = new ScriptedModelProvider.Gate();
        var provider = new ScriptedModelProvider().enqueue(List.of(new ScriptedModelProvider.Step.Start("response-1"),
                new ScriptedModelProvider.Step.Wait(gate),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        try (var runtime = runtime(provider)) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            var run = session.prompt("wait");
            assertTrue(run.abort());
            gate.open();
            assertEquals(io.github.diodeme.ji.agent.AgentEvent.Outcome.ABORTED, run.completion().toCompletableFuture().join().outcome());
            assertEquals(1, session.transcript().size());
        }
    }

    @Test
    void abortWhilePermissionIsPendingFinishesAsAborted() throws Exception {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of("value", "hello")),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.TOOL_USE)));
        var permission = new CompletableFuture<PermissionDecider.Decision>();
        var requested = new AtomicReference<PermissionDecider.Request>();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
                .tool(ToolDefinition.sync("echo", "Echo input", Map.of("type", "object"),
                        (arguments, cancellation) -> ToolDefinition.ToolResult.text("unexpected")))
                .permissionDecider((request, cancellation) -> {
                    requested.set(request);
                    return permission;
                }).idGenerator(new SequentialIds()).build()) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            var run = session.prompt("wait for permission");
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
            while (requested.get() == null && System.nanoTime() < deadline) Thread.onSpinWait();
            assertTrue(requested.get() != null, "permission request was not emitted");
            assertTrue(run.abort());
            assertEquals(io.github.diodeme.ji.agent.AgentEvent.Outcome.ABORTED,
                    run.completion().toCompletableFuture().get(5, TimeUnit.SECONDS).outcome());
            assertEquals(2, session.transcript().size());
        }
    }

    @Test
    void mapsProviderFailureAndLeavesSessionRecoverable() {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Failure("provider.timeout", Map.of("provider", "faux", "phase", "stream"), 0)));
        try (var runtime = runtime(provider)) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            CompletionException failure = assertThrows(CompletionException.class,
                    () -> session.prompt("fail").completion().toCompletableFuture().join());
            JiException error = (JiException) failure.getCause();
            assertEquals(ErrorCode.PROVIDER_TIMEOUT, error.error().code());
            assertEquals(Map.of("provider", "faux", "phase", "stream"), error.error().parameters());
            assertTrue(error.error().traceId().isEmpty());
            assertEquals(1, session.transcript().size());
        }
    }

    @Test
    void rejectedExecutorClearsActiveOwnershipSoRunIdentityCanRetry() {
        var executor = new RejectOnceExecutor();
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
                .executor(executor).idGenerator(new SequentialIds()).build()) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            assertThrows(RejectedExecutionException.class, () -> session.prompt("run-retry", "hello"));
            assertFalse(session.hasActiveRun());
            assertEquals(io.github.diodeme.ji.agent.AgentEvent.Outcome.COMPLETED,
                    session.prompt("run-retry", "hello").completion().toCompletableFuture().join().outcome());
            assertEquals(1, provider.capturedRequests().size());
        }
    }

    @Test
    void closedRuntimeUsesPublicStructuredError() {
        var runtime = runtime(new ScriptedModelProvider());
        runtime.close();
        List<JiException> failures = List.of(
                assertThrows(JiException.class,
                        () -> runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."))),
                assertThrows(JiException.class, () -> runtime.loadSession("session-1")),
                assertThrows(JiException.class, runtime::sessionStore));
        for (JiException closed : failures) {
            assertEquals("runtime.closed", closed.error().code().code());
            assertEquals(Map.of("resource", "agent-runtime"), closed.error().parameters());
        }
    }

    @Test
    void missingSessionUsesPublicStructuredError() {
        try (var runtime = runtime(new ScriptedModelProvider())) {
            JiException missing = assertThrows(JiException.class, () -> runtime.loadSession("missing"));
            assertEquals(ErrorCode.SESSION_NOT_FOUND, missing.error().code());
            assertEquals(Map.of("sessionId", "missing"), missing.error().parameters());
        }
    }

    @Test
    void closedSessionUsesPublicStructuredError() {
        try (var runtime = runtime(new ScriptedModelProvider())) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            session.close();
            JiException closed = assertThrows(JiException.class, () -> session.prompt("hello"));
            assertEquals(ErrorCode.SESSION_NOT_FOUND, closed.error().code());
            assertEquals(session.id(), closed.error().parameters().get("sessionId"));
        }
    }

    @Test
    void rejectsConcurrentRunsInsteadOfSilentlyQueueing() {
        var gate = new ScriptedModelProvider.Gate();
        var provider = new ScriptedModelProvider().enqueue(List.of(new ScriptedModelProvider.Step.Wait(gate),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        try (var runtime = runtime(provider)) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            var first = session.prompt("one");
            JiException conflict = assertThrows(JiException.class, () -> session.prompt("two"));
            assertEquals(ErrorCode.SESSION_ACTIVE_RUN, conflict.error().code());
            assertEquals(session.id(), conflict.error().parameters().get("sessionId"));
            assertEquals(first.id(), conflict.error().parameters().get("runId"));
            first.abort();
            gate.open();
            first.completion().toCompletableFuture().join();
        }
    }

    @Test
    void promptContributorsReachProviderInDeterministicBudgetedSystemPrompt() {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        PromptContributor contributor = new PromptContributor() {
            @Override public ContributorId id() { return new ContributorId("project-context"); }
            @Override public ResourceDescriptor.SourceId source() { return new ResourceDescriptor.SourceId("fixture"); }
            @Override public int priority() { return 10; }
            @Override public int tokenBudget() { return 100; }
            @Override public Contribution contribute(PromptContext context) {
                return new Contribution("Use the repository conventions.");
            }
        };
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
                .promptContributor(contributor).promptTokenCounter(String::length).promptTokenBudget(100)
                .idGenerator(new SequentialIds()).build()) {
            runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."))
                    .prompt("hello").completion().toCompletableFuture().join();
            String system = provider.capturedRequests().getFirst().systemPrompt();
            assertTrue(system.contains("Use the repository conventions."));
            assertTrue(system.contains("working in ."));
        }
    }

    @Test
    void builtInPromptsHaveSymmetricEnglishAndChineseContracts() {
        var templates = BuiltinPromptTemplates.templates();
        assertEquals(4, templates.size());
        assertEquals(templates.stream().filter(value -> value.locale().equals("en")).map(value -> value.id()).sorted().toList(),
                templates.stream().filter(value -> value.locale().equals("zh-CN")).map(value -> value.id()).sorted().toList());
        assertEquals(templates.stream().filter(value -> value.locale().equals("en")).map(value -> value.variableContract()).toList(),
                templates.stream().filter(value -> value.locale().equals("zh-CN")).map(value -> value.variableContract()).toList());
    }

    private static ScriptedModelProvider toolScript() {
        return new ScriptedModelProvider()
                .enqueue(List.of(new ScriptedModelProvider.Step.Start("response-1"),
                        new ScriptedModelProvider.Step.Text(""),
                        new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of("value", "hello")),
                        new ScriptedModelProvider.Step.Complete(FIRST_USAGE, ModelStreamEvent.StopReason.TOOL_USE)))
                .enqueue(List.of(new ScriptedModelProvider.Step.Start("response-2"),
                        new ScriptedModelProvider.Step.Text("do"), new ScriptedModelProvider.Step.Text("ne"),
                        new ScriptedModelProvider.Step.Complete(SECOND_USAGE, ModelStreamEvent.StopReason.STOP)));
    }

    private static io.github.diodeme.ji.agent.AgentRuntime runtime(ScriptedModelProvider provider) {
        return new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
                .idGenerator(new SequentialIds()).build();
    }

    private static final class SequentialIds implements io.github.diodeme.ji.agent.RuntimeConfiguration.IdGenerator {
        private final AtomicInteger sequence = new AtomicInteger();
        @Override public String next(String scope) { return scope + "-" + sequence.incrementAndGet(); }
    }

    private static final class RejectOnceExecutor extends AbstractExecutorService {
        private final java.util.concurrent.ExecutorService delegate = java.util.concurrent.Executors.newSingleThreadExecutor();
        private final AtomicBoolean rejected = new AtomicBoolean();

        @Override public void execute(Runnable command) {
            if (rejected.compareAndSet(false, true)) throw new RejectedExecutionException("injected rejection");
            delegate.execute(command);
        }
        @Override public void shutdown() { delegate.shutdown(); }
        @Override public List<Runnable> shutdownNow() { return delegate.shutdownNow(); }
        @Override public boolean isShutdown() { return delegate.isShutdown(); }
        @Override public boolean isTerminated() { return delegate.isTerminated(); }
        @Override public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
            return delegate.awaitTermination(timeout, unit);
        }
    }
}

