import org.junit.jupiter.api.Test;

class AgentRuntimeContractTest {
    private static final Usage FIRST_USAGE = new Usage(3, 2, 0, 0, 5);
    private static final Usage SECOND_USAGE = new Usage(5, 3, 0, 0, 7);

    @Test
    void completesStreamingToolPermissionUsageAndReloadFromCanonicalStore() {
        var provider = toolScript();
        var store = new MemorySessionRepository();
        var executions = new AtomicInteger();
        var observedDurableRunningState = new AtomicBoolean();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(store)
                .tool(ToolDefinition.sync("echo", "Echo input", Map.of("type", "object"), (arguments, cancellation) -> {
                    executions.incrementAndGet();
                    var document = store.load(store.list().getFirst().sessionId()).orElseThrow();
                    var turn = document.execution().activeRun().orElseThrow().turns().getLast();
                    observedDurableRunningState.set(
                            turn.tools().getFirst().status()
                                    == io.github.diodeme.ji.session.model.CanonicalSessionState.ToolStatus.RUNNING
                            && turn.permissions().getFirst().outcome().orElseThrow()
                                    == io.github.diodeme.ji.session.model.CanonicalSessionState.PermissionOutcome.ALLOWED);
                    return ToolDefinition.ToolResult.text("echoed " + arguments.get("value"));
                }))
                .permissionDecider((request, cancellation) -> java.util.concurrent.CompletableFuture.completedFuture(
                        PermissionDecider.Decision.allow(request, Instant.parse("2026-09-04T00:00:01Z"))))
                .idGenerator(new SequentialIds()).clock(Clock.fixed(Instant.parse("2026-09-04T00:00:00Z"), ZoneOffset.UTC))
                .build()) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            assertEquals(io.github.diodeme.ji.agent.AgentEvent.Outcome.COMPLETED,
                    session.prompt("hello").completion().toCompletableFuture().join().outcome());
            assertEquals(1, executions.get());
            assertTrue(observedDurableRunningState.get());
            assertEquals(List.of("hello", "", "echoed hello", "done"), session.transcript().stream().map(message -> message.text()).toList());
            assertEquals("call-1", session.transcript().get(2).toolCallId().orElseThrow());
            assertEquals(13, store.load(session.id()).orElseThrow().usage().totalTokens());
            assertEquals(session.transcript(), runtime.loadSession(session.id()).transcript());
            assertEquals(2, provider.capturedRequests().size());
            assertEquals(3, provider.capturedRequests().get(1).messages().size());
        }
    }

    @Test
    void restartPauseRejectsLateToolCompletionWithoutRollingBackCanonicalState() throws Exception {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of("value", "hello")),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.TOOL_USE)));
        var store = new MemorySessionRepository();
        var effectStarted = new java.util.concurrent.CountDownLatch(1);
        var releaseEffect = new java.util.concurrent.CountDownLatch(1);
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(store)
                .tool(ToolDefinition.sync("echo", "Echo input", Map.of("type", "object"),
                        (arguments, cancellation) -> {
                            effectStarted.countDown();
                            releaseEffect.await(5, TimeUnit.SECONDS);
                            return ToolDefinition.ToolResult.text("late");
                        }))
                .permissionDecider((request, cancellation) -> CompletableFuture.completedFuture(
                        PermissionDecider.Decision.allow(request, Instant.now())))
                .idGenerator(new SequentialIds()).build()) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            var run = session.prompt("run tool");
            assertTrue(effectStarted.await(5, TimeUnit.SECONDS));
            var active = store.load(session.id()).orElseThrow();
            store.update(session.id(), active.revision(), value -> value.pauseAfterRestart());
            releaseEffect.countDown();

            CompletionException failure = assertThrows(CompletionException.class,
                    () -> run.completion().toCompletableFuture().join());
            assertEquals(ErrorCode.OPERATION_STALE_COMPLETION, ((JiException) failure.getCause()).error().code());
            var paused = store.load(session.id()).orElseThrow().execution().activeRun().orElseThrow();
            assertEquals(io.github.diodeme.ji.session.model.CanonicalSessionState.RunStatus.PAUSED, paused.status());
            assertEquals(io.github.diodeme.ji.session.model.CanonicalSessionState.ToolStatus.PAUSED,
                    paused.turns().getLast().tools().getFirst().status());
        } finally {
            releaseEffect.countDown();
        }
    }

    @Test
    void restartPauseRejectsLateProviderCompletionWithoutRollingBackCanonicalState() throws Exception {
        var gate = new ScriptedModelProvider.Gate();
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Wait(gate),
                new ScriptedModelProvider.Step.Text("late"),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        var store = new MemorySessionRepository();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(store)
                .idGenerator(new SequentialIds()).build()) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            var run = session.prompt("wait for provider");
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
            while (provider.capturedRequests().isEmpty() && System.nanoTime() < deadline) Thread.onSpinWait();
            assertEquals(1, provider.capturedRequests().size());
            SessionDocument active = store.load(session.id()).orElseThrow();
            store.update(session.id(), active.revision(), SessionDocument::pauseAfterRestart);
            gate.open();

            CompletionException failure = assertThrows(CompletionException.class,
                    () -> run.completion().toCompletableFuture().join());
            assertEquals(ErrorCode.OPERATION_STALE_COMPLETION, ((JiException) failure.getCause()).error().code());
            SessionDocument paused = store.load(session.id()).orElseThrow();
            assertEquals(io.github.diodeme.ji.session.model.CanonicalSessionState.RunStatus.PAUSED,
                    paused.execution().activeRun().orElseThrow().status());
            assertEquals(List.of("wait for provider"),
                    paused.snapshot().transcript().stream().map(Message::text).toList());
        } finally {
            gate.open();
        }
    }

