    @Test
    void abortBeforeProviderDispatchCompletesTheCanonicalRunAsAborted() throws Exception {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        var executor = java.util.concurrent.Executors.newSingleThreadExecutor();
        var blockerStarted = new CountDownLatch(1);
        var releaseExecutor = new CountDownLatch(1);
        executor.execute(() -> {
            blockerStarted.countDown();
            try {
                releaseExecutor.await(5, TimeUnit.SECONDS);
            } catch (InterruptedException exception) {
                Thread.currentThread().interrupt();
            }
        });
        assertTrue(blockerStarted.await(5, TimeUnit.SECONDS));
        try (var runtime = new AgentRuntimeBuilder().provider(provider)
                .sessionRepository(new MemorySessionRepository())
                .idGenerator(new SequentialIds()).executor(executor).build()) {
            AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            AgentRun run = session.prompt("one");
            assertTrue(run.abort());
            releaseExecutor.countDown();

            AgentRun.Result result = run.completion().toCompletableFuture().get(5, TimeUnit.SECONDS);
            assertEquals(AgentEvent.Outcome.ABORTED, result.outcome());
            assertTrue(provider.capturedRequests().isEmpty());
        } finally {
            releaseExecutor.countDown();
            executor.shutdownNow();
        }
    }

