            resumed.completion().toCompletableFuture().join();

            var completed = store.load(session.id()).orElseThrow().execution().completedRuns().getFirst();
            assertEquals("run-recover", completed.id().value());
            assertEquals(2, completed.turns().getFirst().attempts().size());
