                    completed.turns().getFirst().attempts().getFirst().outcome().orElseThrow());
        }
    }

    @Test
    void restartResumeExecutesTheWholeDurableToolBatchBeforeCallingProvider() {
        var store = new MemorySessionRepository();
        var model = new ModelRef("faux", "faux-1");
        Instant startedAt = Instant.parse("2026-09-04T00:00:00Z");
        SessionDocument empty = store.create("session-tool-recover", model, ".", startedAt);
        Message prompt = new Message("message-user", Message.Role.USER,
                List.of(new io.github.diodeme.ji.ai.Content.Text("run both tools")), startedAt);
        SessionDocument running = store.update(empty.metadata().sessionId(), empty.revision(), document ->
                document.startRun(new SessionDocument.RunStart(
                        "run-recover", "turn-recover", "attempt-model", "result-model", prompt,
                        "record-run", "record-model", startedAt)));
        Message assistant = new Message("message-assistant", Message.Role.ASSISTANT, List.of(
                new io.github.diodeme.ji.ai.Content.ToolCall("call-a", "tool-a", Map.of("value", "a")),
                new io.github.diodeme.ji.ai.Content.ToolCall("call-b", "tool-b", Map.of("value", "b"))),
                startedAt.plusSeconds(1));
        CanonicalSessionState.Run sourceRun = running.execution().activeRun().orElseThrow();
        CanonicalSessionState.Turn sourceTurn = sourceRun.turns().getLast();
        SessionDocument waiting = store.update(running.metadata().sessionId(), running.revision(), document ->
                document.completeAssistantWithTools(new SessionDocument.AssistantCompletion(
                        sourceRun.id().value(), sourceRun.revision(), sourceTurn.id().value(), sourceTurn.revision(),
                        sourceTurn.attempts().getLast().id().value(), sourceTurn.attempts().getLast().revision(),
                        List.of(assistant), Usage.ZERO, List.of(
                        new SessionDocument.ToolStart("tool-a-execution", "tool-a-attempt", "tool-a-result",
                                "call-a", "tool-a", CanonicalSessionState.ToolRetryContract.READ_ONLY,
                                Optional.empty(), Optional.empty(), "record-tool-a"),
                        new SessionDocument.ToolStart("tool-b-execution", "tool-b-attempt", "tool-b-result",
                                "call-b", "tool-b", CanonicalSessionState.ToolRetryContract.IDEMPOTENT,
                                Optional.empty(), Optional.empty(), "record-tool-b")),
                        "record-usage", startedAt.plusSeconds(1))));
        for (String executionId : List.of("tool-a-execution", "tool-b-execution")) {
            SessionDocument current = store.load(waiting.metadata().sessionId()).orElseThrow();
            CanonicalSessionState.Run run = current.execution().activeRun().orElseThrow();
            CanonicalSessionState.Turn turn = run.turns().getLast();
            CanonicalSessionState.ToolExecution tool = turn.tools().stream()
                    .filter(candidate -> candidate.id().value().equals(executionId)).findFirst().orElseThrow();
            CanonicalSessionState.Attempt attempt = tool.attempts().getLast();
            store.update(current.metadata().sessionId(), current.revision(), document -> document.startTool(
                    new SessionDocument.ToolExecutionStart(
                            run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                            tool.id().value(), tool.revision(), attempt.id().value(), attempt.revision(),
                            "record-start-" + executionId, startedAt.plusSeconds(2))));
        }

        var firstEffects = new AtomicInteger();
        var secondEffects = new AtomicInteger();
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Text("done"),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(store)
                .tool(ToolDefinition.sync("tool-a", "first", Map.of("type", "object"),
                                (arguments, cancellation) -> {
                                    firstEffects.incrementAndGet();
                                    return ToolDefinition.ToolResult.text("first-result");
                                }).alwaysAllow().retryAs(io.github.diodeme.ji.extension.ToolRetryContract.READ_ONLY))
                .tool(ToolDefinition.sync("tool-b", "second", Map.of("type", "object"),
                                (arguments, cancellation) -> {
                                    secondEffects.incrementAndGet();
                                    return ToolDefinition.ToolResult.text("second-result");
                                }).alwaysAllow().retryAs(io.github.diodeme.ji.extension.ToolRetryContract.IDEMPOTENT))
                .idGenerator(new SequentialIds()).build()) {
            AgentSession session = runtime.loadSession("session-tool-recover");
            assertEquals(CanonicalSessionState.TurnPhase.WAITING_FOR_TOOLS,
                    store.load(session.id()).orElseThrow().execution().activeRun().orElseThrow()
                            .turns().getLast().pausedFrom().orElseThrow());

            AgentRun resumed = session.resume();
            assertEquals("run-recover", resumed.id());
            assertEquals(AgentEvent.Outcome.COMPLETED,
                    resumed.completion().toCompletableFuture().join().outcome());

            assertEquals(1, firstEffects.get());
            assertEquals(1, secondEffects.get());
            assertEquals(1, provider.capturedRequests().size());
            assertEquals(List.of("run both tools", "", "first-result", "second-result", "done"),
                    session.transcript().stream().map(Message::text).toList());
            CanonicalSessionState.Run completed = store.load(session.id()).orElseThrow()
                    .execution().completedRuns().getFirst();
            assertTrue(completed.turns().getFirst().tools().stream().allMatch(tool ->
                    tool.attempts().size() == 2
                            && tool.attempts().getFirst().outcome().orElseThrow()
                            == CanonicalSessionState.AttemptOutcome.SUPERSEDED
                            && tool.attempts().getLast().outcome().orElseThrow()
                            == CanonicalSessionState.AttemptOutcome.SUCCEEDED));
        }
    }

