    @Test
    void restartDuringOverflowCompactionResumesTheOriginalRunAndContinuousAttempt() {
        var store = new MemorySessionRepository();
        var model = new ModelRef("faux", "faux-1");
        String sessionId;
        var seedProvider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Text("old answer"),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        try (var runtime = new AgentRuntimeBuilder().provider(seedProvider).sessionRepository(store)
                .idGenerator(new SequentialIds()).build()) {
            AgentSession session = runtime.newSession(new SessionOptions(model, "."));
            sessionId = session.id();
            session.prompt("old request").completion().toCompletableFuture().join();
        }

        Instant interruptedAt = Instant.parse("2026-09-04T00:00:00Z");
        Message prompt = new Message("message-overflow", Message.Role.USER,
                List.of(new io.github.diodeme.ji.ai.Content.Text("overflow request")), interruptedAt);
        SessionDocument beforeRun = store.load(sessionId).orElseThrow();
        SessionDocument running = store.update(sessionId, beforeRun.revision(), document -> document.startRun(
                new SessionDocument.RunStart(
                        "run-overflow", "turn-overflow", "attempt-provider-1", "result-provider-1", prompt,
                        "record-run-overflow", "record-provider-attempt-1", interruptedAt)));
        store.update(sessionId, running.revision(), document -> document.startCompaction(
                new SessionDocument.CompactionStart(
                        "compaction-overflow", "attempt-compaction-1", "result-compaction-1",
                        List.of(prompt.id()), 12, "", SessionDocument.CompactionReason.OVERFLOW,
                        Optional.of("run-overflow"), "record-compaction-overflow",
                        "record-compaction-attempt-1", interruptedAt.plusSeconds(1))));

        var resumedProvider = new ScriptedModelProvider()
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("recovered summary"),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)))
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("recovered answer"),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        var resumedIds = new AtomicInteger();
        try (var runtime = new AgentRuntimeBuilder().provider(resumedProvider).sessionRepository(store)
                .compactionPolicy(new CompactionPolicy(true, java.util.OptionalLong.of(10), 2, 1))
                .idGenerator(scope -> "resumed-" + scope + "-" + resumedIds.incrementAndGet()).build()) {
            AgentSession session = runtime.loadSession(sessionId);
            SessionDocument paused = store.load(sessionId).orElseThrow();
            CanonicalSessionState.Run pausedRun = paused.execution().activeRun().orElseThrow();
            assertEquals("run-overflow", pausedRun.id().value());
            assertEquals("turn-overflow", pausedRun.turns().getLast().id().value());
            assertEquals(CanonicalSessionState.TurnPhase.WAITING_FOR_COMPACTION,
                    pausedRun.turns().getLast().pausedFrom().orElseThrow());

            session.resumeCompaction().completion().toCompletableFuture().join();
            awaitRequestCount(resumedProvider, 2);
            CanonicalSessionState.Run completed = awaitCompletedRun(store, sessionId, "run-overflow");

            assertEquals("turn-overflow", completed.turns().getLast().id().value());
            assertEquals(CanonicalSessionState.RunOutcome.COMPLETED, completed.outcome().orElseThrow());
            assertEquals(List.of(1, 2), completed.turns().getLast().attempts().stream()
                    .map(CanonicalSessionState.Attempt::number).toList());
            assertEquals(CanonicalSessionState.AttemptOutcome.FAILED,
                    completed.turns().getLast().attempts().getFirst().outcome().orElseThrow());
            assertEquals(CanonicalSessionState.AttemptOutcome.SUCCEEDED,
                    completed.turns().getLast().attempts().getLast().outcome().orElseThrow());
            CanonicalSessionState.Compaction compaction = store.load(sessionId).orElseThrow()
                    .execution().compactions().getLast();
            assertEquals(List.of(1, 2), compaction.attempts().stream()
                    .map(CanonicalSessionState.Attempt::number).toList());
            assertEquals(CanonicalSessionState.AttemptOutcome.SUPERSEDED,
                    compaction.attempts().getFirst().outcome().orElseThrow());
            assertEquals(CanonicalSessionState.AttemptOutcome.SUCCEEDED,
                    compaction.attempts().getLast().outcome().orElseThrow());
            assertEquals(1, session.transcript().stream()
                    .filter(message -> message.role() == Message.Role.USER)
                    .filter(message -> message.text().equals("overflow request")).count());
        }
    }

