    private static io.github.diodeme.ji.agent.AgentRuntime runtime(ScriptedModelProvider provider) {
        return new AgentRuntimeBuilder().provider(provider).sessionRepository(new MemorySessionRepository())
                .idGenerator(new SequentialIds()).build();
    }

    private static final class SequentialIds implements io.github.diodeme.ji.agent.RuntimeConfiguration.IdGenerator {
        private final AtomicInteger sequence = new AtomicInteger();
        @Override public String next(String scope) { return scope + "-" + sequence.incrementAndGet(); }
    }

    private static void awaitRequestCount(ScriptedModelProvider provider, int expected) {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
        while (provider.capturedRequests().size() < expected && System.nanoTime() < deadline) {
            Thread.onSpinWait();
        }
        assertEquals(expected, provider.capturedRequests().size());
    }

    private static CanonicalSessionState.Run awaitCompletedRun(
            MemorySessionRepository store, String sessionId, String runId) {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
        while (System.nanoTime() < deadline) {
            Optional<CanonicalSessionState.Run> completed = store.load(sessionId).stream()
                    .flatMap(document -> document.execution().completedRuns().stream())
                    .filter(run -> run.id().value().equals(runId))
                    .findFirst();
            if (completed.isPresent()) return completed.orElseThrow();
            Thread.onSpinWait();
        }
        throw new AssertionError("Run did not complete: " + runId);
    }

    private static final class RejectOnceExecutor extends AbstractExecutorService {
        private final java.util.concurrent.ExecutorService delegate = java.util.concurrent.Executors.newSingleThreadExecutor();
        private final AtomicBoolean rejected = new AtomicBoolean();

        @Override public void execute(Runnable command) {
            if (rejected.compareAndSet(false, true)) throw new RejectedExecutionException("injected rejection");
            delegate.execute(command);
        }
        @Override public void shutdown() { delegate.shutdown(); }
        @Override public List<Runnable> shutdownNow() { return delegate.shutdownNow(); }
        @Override public boolean isShutdown() { return delegate.isShutdown(); }
        @Override public boolean isTerminated() { return delegate.isTerminated(); }
        @Override public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
            return delegate.awaitTermination(timeout, unit);
        }
    }

    private static final class BlockingTerminalRepository implements SessionRepository {
        private final MemorySessionRepository delegate = new MemorySessionRepository();
        private final AtomicBoolean blockOnce = new AtomicBoolean();
        private final CountDownLatch terminalCommitted = new CountDownLatch(1);
        private final CountDownLatch releaseTerminal = new CountDownLatch(1);

        @Override
        public SessionDocument create(String sessionId, ModelRef model, String workingDirectory, Instant createdAt) {
            return delegate.create(sessionId, model, workingDirectory, createdAt);
        }

        @Override
        public Optional<SessionDocument> load(String sessionId) {
            return delegate.load(sessionId);
        }

        @Override
        public List<SessionDocument.Metadata> list() {
            return delegate.list();
        }

        @Override
        public SessionDocument update(
                String sessionId, long expectedRevision, UnaryOperator<SessionDocument> transition) {
            SessionDocument next = delegate.update(sessionId, expectedRevision, transition);
            if (next.execution().activeRun().isEmpty() && blockOnce.compareAndSet(false, true)) {
                terminalCommitted.countDown();
                try {
                    if (!releaseTerminal.await(10, TimeUnit.SECONDS)) {
                        throw new IllegalStateException("terminal commit test release timed out");
                    }
                } catch (InterruptedException interrupted) {
                    Thread.currentThread().interrupt();
                    throw new IllegalStateException("terminal commit test interrupted", interrupted);
                }
            }
            return next;
        }

        @Override
        public SessionDocument fork(
                String sourceSessionId, String newSessionId, String lane, Optional<String> targetEntryId,
                SessionDocument.ForkPosition position, Instant createdAt, long expectedSourceRevision) {
            return delegate.fork(sourceSessionId, newSessionId, lane, targetEntryId, position,
                    createdAt, expectedSourceRevision);
        }

        @Override
        public void delete(String sessionId, long expectedRevision) {
            delegate.delete(sessionId, expectedRevision);
        }

        private boolean awaitTerminalCommit() throws InterruptedException {
            return terminalCommitted.await(5, TimeUnit.SECONDS);
        }

        private void releaseTerminalCommit() {
            releaseTerminal.countDown();
        }
    }
